SQL:
-- sgl.query(name: AuthorTitles, command: many)
WITH author_books AS (
    SELECT d.author_id, d.title FROM (SELECT author_id, title FROM books) d
)
SELECT author_id, count(*) AS book_count FROM author_books GROUP BY author_id;

Template:
WITH author_books AS (
    SELECT d.author_id, d.title FROM (SELECT author_id, title FROM books) d
)
SELECT ⟨c0:author_id⟩, ⟨c1 aliased:count(*)⟩ AS book_count FROM author_books GROUP BY author_id;

SQL:
-- sgl.query(name: NestedWith, command: many)
WITH outer_rows AS (
    WITH inner_rows AS (SELECT id, name FROM authors)
    SELECT id, name FROM inner_rows
)
SELECT id, name FROM outer_rows;

Template:
WITH outer_rows AS (
    WITH inner_rows AS (SELECT id, name FROM authors)
    SELECT id, name FROM inner_rows
)
SELECT ⟨c0:id⟩, ⟨c1:name⟩ FROM outer_rows;

SQL:
-- sgl.query(name: StarOfAnEarlierCTE, command: many)
WITH first_rows AS (SELECT id, name FROM authors), second_rows AS (SELECT * FROM first_rows)
SELECT * FROM second_rows;

-- sgl.query(name: JoinedEarlierCTE, command: many)
WITH named AS (SELECT id, name FROM authors), titled AS (SELECT b.title, n.name FROM books b JOIN named n ON n.id = b.author_id)
SELECT title, name FROM titled;

-- sgl.query(name: CTEInsideADerivedUnion, command: many)
WITH a AS (SELECT id, name FROM authors)
SELECT u.id, u.name FROM (SELECT id, name FROM a UNION ALL SELECT id, name FROM a) u;

-- sgl.query(name: LateralInsideACTE, command: many)
WITH latest AS (
    SELECT a.name, l.title FROM authors a CROSS JOIN LATERAL (SELECT b.title FROM books b WHERE b.author_id = a.id ORDER BY b.id DESC LIMIT 1) l
)
SELECT name, title FROM latest;

